window.SUBJECTS = window.SUBJECTS || [];
window.SUBJECTS.push({"id":"hist","n":"History","tab":"History","w":"Ancient and medieval India, British India, and the freedom struggle.","topics":[{"id":"ancient","n":"Ancient India","qs":[{"id":"q0051","q":"At which of the following places was the Sarnath image of standing Bodhisattvas made?","o":["Mathura","Gandhar","Amaravati","Varanasi"],"a":0,"x":"The standing Bodhisattva found at Sarnath was carved in Mathura's red sandstone in the Kushana period and dedicated by the monk Friar Bala.","e":"Kushana-era schools: Mathura (red sandstone, Indian style), Gandhara (grey schist, Greek-influenced), Amaravati (white marble).","src":["ASO 18 Aug 2025 S2"]},{"id":"q1571","q":"Which of the following arts was practised on a large scale by the people of Harappa?","o":["Aluminium casting","Iron casting","Brass casting","Bronze casting"],"a":3,"x":"Harappans practised bronze casting widely, using the lost-wax technique; the Dancing Girl of Mohenjo-daro is the best-known example. They did not use iron.","e":"Bronze is an alloy of copper and tin.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q0699","q":"Who among the following was the founder of the Chalukya Dynasty?","o":["Aditya I","Krishna I","Pulakeshin I","Kokalla I"],"a":2,"x":"Pulakeshin I founded the Chalukya dynasty of Badami (Vatapi) around 543 CE.","e":"Pulakeshin II defeated Harsha on the Narmada.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0739","q":"Amongst the following, who is known as the author of Arthashastra?","o":["Kalidasa","Varahamihira","Aryabhatta","Kautilya"],"a":3,"x":"The Arthashastra, a treatise on statecraft and economics, is credited to Kautilya (Chanakya), the adviser to Chandragupta Maurya.","e":"It was rediscovered in 1905 by R. Shamasastry.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1317","q":"In which of the following cities was the Sangam assemblies held?","o":["Nagapattinam","Thiruvarur","Thiruvallur","Madurai"],"a":3,"x":"The three Tamil Sangams (literary assemblies) are traditionally said to have been held at Madurai under Pandya patronage.","e":"Sangam literature: Tolkappiyam, Ettuthokai, Pattuppattu.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1340","q":"Which among the following vedas is concerned with warfare?","o":["Ayurveda","Rigveda","Dhanurveda","Gandharva Veda"],"a":2,"x":"Dhanurveda, an upaveda linked with the Yajurveda, is the science of archery and warfare.","e":"Upavedas: Ayurveda (Rigveda), Dhanurveda (Yajurveda), Gandharvaveda (Samaveda), Shilpaveda (Atharvaveda).","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1361","q":"Who among the following is often called the first empire builder of Indian history?","o":["Mahapadma Nanda","Chandragupta Maurya","Ashoka","Dhana Nanda"],"a":0,"x":"Mahapadma Nanda, founder of the Nanda dynasty of Magadha, is often called the first empire-builder of Indian history; the Puranas call him 'the destroyer of all Kshatriyas'.","e":"The last Nanda king, Dhana Nanda, was overthrown by Chandragupta Maurya.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1101","q":"At which archaeological site is the famous Great Bath of Harappan architecture located?","o":["Harappa","Kalibangan","Mohenjo-daro","Lothal"],"a":2,"x":"The Great Bath, a large brick tank with steps and drains that is probably ritual, is at Mohenjo-daro in Sindh.","e":"Lothal has a dockyard; Kalibangan has ploughed fields and fire altars.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1218","q":"At which site was the famous Harappan sculpture 'Dancing Girl' found?","o":["Kalibangan","Lothal","Mohenjo-daro","Harappa"],"a":2,"x":"The bronze 'Dancing Girl', made by the lost-wax (cire perdue) method, was found at Mohenjo-daro.","e":"The steatite 'Priest-King' bust is also from Mohenjo-daro.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1265","q":"The Harappan civilization is famous for its well-planned cities. Which of the following features is commonly found in Harappan cities?","o":["Grid pattern of streets","Circular roads","Random building construction","Elevated platforms"],"a":0,"x":"Harappan cities were planned on a grid: streets cutting at right angles, covered drains, baked-brick houses, and often a raised citadel.","e":"Mohenjo-daro's streets ran north–south and east–west.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1490","q":"The caves of Bhimbetka in Madhya Pradesh are famous for _______________.","o":["Rock-cut temples","Ancient manuscripts","Buddhist stupas","Rock paintings"],"a":3,"x":"The Bhimbetka rock shelters near Bhopal, Madhya Pradesh, are famous for prehistoric rock paintings, some over 10,000 years old; UNESCO listed them in 2003.","e":"V. S. Wakankar discovered them in 1957.","src":["TGT 29 Aug 2025"]},{"id":"q1515","q":"What form of portable art is found in the Indian Palaeolithic period?","o":["Metal sculptures","Wooden carvings","Ostrich eggshell beads and engraved fragments","Clay figurines"],"a":2,"x":"Portable art from India's Upper Palaeolithic includes ostrich eggshell beads and engraved eggshell fragments, as found at Patne (Maharashtra).","e":"Bhimbetka (Madhya Pradesh) has the famous prehistoric rock paintings.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1531","q":"Which regions were part of Ashoka's empire where kingdoms emerged after the decline of Mauryan rule?","o":["Deccan and Gujarat","Deccan and Kalinga","Gujarat and Rajasthan","Kalinga and Bengal"],"a":1,"x":"After the Mauryan decline, regional kingdoms rose in parts of Ashoka's former empire: the Satavahanas in the Deccan and Kharavela's Mahameghavahana dynasty in Kalinga.","e":"Kharavela's Hathigumpha inscription is at Udayagiri, near Bhubaneswar.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1556","q":"Bori and Moregaon are two Lower Palaeolithic sites of the State of ________.","o":["Tamil Nadu","Maharashtra","Haryana","Gujarat"],"a":1,"x":"Bori (Pune district) and Morgaon are Lower Palaeolithic sites in Maharashtra; Bori is among the oldest in India.","e":"Other Lower Palaeolithic sites: Attirampakkam (Tamil Nadu), Hunsgi (Karnataka), Bhimbetka.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0764","q":"The Gupta rulers issued a large number of ________ coins called dinars.","o":["Gold","Bronze","Silver","Copper"],"a":0,"x":"The Gupta rulers issued many gold coins called dinars; Samudragupta's coins show him playing the veena.","e":"The Kushanas were the first to issue gold coins in India on a large scale.","src":["PGT 25 Sep 2025"]},{"id":"q0787","q":"In the Iron Age, horse burials have been reported from ________ near Nagpur in Maharashtra.","o":["Junapani","Padaliya","Suakhedi","Rondia"],"a":0,"x":"Megalithic (Iron Age) burials with horse remains have been found at Junapani near Nagpur, Maharashtra.","e":"Megaliths are stone-marked burials common in the Deccan and south India.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0793","q":"Parishishtaparvan was written by ________.","o":["Vishakhadatta","Harishena","Hemachandra","Kalhana"],"a":2,"x":"Parishishtaparvan (12th century), a Jain text, was written by Hemachandra; it records Chandragupta Maurya's conversion to Jainism.","e":"Vishakhadatta wrote Mudrarakshasa; Kalhana wrote Rajatarangini; Harishena wrote the Prayag Prashasti.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0801","q":"Which of the following taxes levied during the Gupta period refers to forced labour?","o":["Vishti","Bali","Udranga","Uparikara"],"a":0,"x":"Vishti was forced, unpaid labour demanded by the state in the Gupta period.","e":"Other Gupta levies: bali (extra tax), udranga (land tax), uparikara (tax on temporary tenants).","src":["PGT 22 Sep 2025"]},{"id":"q0856","q":"The fourth Buddhist Council at Kundalavana was organised under the patronage of which of the following kings?","o":["Kanishka","Ashoka","Pushyamitra Shunga","Rudradaman I"],"a":0,"x":"The Fourth Buddhist Council was held at Kundalavana in Kashmir under Kanishka, chaired by Vasumitra with Ashvaghosha; Buddhism split into Mahayana and Hinayana.","e":"Councils: 1st Rajagriha (Ajatashatru), 2nd Vaishali (Kalashoka), 3rd Pataliputra (Ashoka).","src":["PGT 14 Jul 2025"]},{"id":"q0857","q":"After defeating Harshavardhana in circa 630 CE, who among the following kings acquired the title of ‘Dakshinapatheshvara’ (lord of the south)?","o":["Pulakesin II","Mahendravarman","Narasimhavarman I","Pulakesin I"],"a":0,"x":"Pulakeshin II of Badami defeated Harshavardhana on the Narmada around 630 CE and took the title 'Dakshinapatheshvara' (Lord of the South).","e":"The Aihole inscription by Ravikirti records this victory.","src":["PGT 14 Jul 2025"]}]},{"id":"medieval","n":"Medieval India","qs":[{"id":"q0002","q":"Which of the following was the capital of the Kakatiya dynasty?","o":["Orugallu","Madurai","Kollam","Rameswaram"],"a":0,"x":"Orugallu, today's Warangal in Telangana, was the Kakatiya capital. Rudrama Devi, one of India's few ruling queens, governed from here.","e":"The Kakatiya Kala Thoranam gateway of Warangal Fort sits on Telangana's state emblem.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0054","q":"The Battle of Ghagra (1529) was fought between Babur and which group?","o":["Afghan rebels led by Mahmud Lodi","Portuguese traders in Gujarat","Rajputs led by Rana Sanga","Lodis of Delhi"],"a":0,"x":"At the Battle of Ghaghra (1529) in Bihar, Babur defeated the Afghan chiefs of eastern India led by Mahmud Lodi. It was his last major battle.","e":"Babur's big three: Panipat 1526 (Ibrahim Lodi), Khanwa 1527 (Rana Sanga), Chanderi 1528 (Medini Rai).","src":["ASO 18 Aug 2025 S2"]},{"id":"q0058","q":"To establish stable administration in the Deccan, which of the following Sultans of Delhi appointed Amiran-i- sada/Sada Amir?","o":["Firoz Shah Tughlaq","Ghiyasuddin Balban","Alauddin Khalji","Mohammad bin Tughlaq"],"a":3,"x":"Muhammad bin Tughlaq appointed amiran-i-sada (commanders over groups of a hundred villages) to run the Deccan after shifting his capital to Daulatabad.","e":"Their revolt later led to the founding of the Bahmani kingdom (1347).","src":["ASO 18 Aug 2025 S2"]},{"id":"q0085","q":"After the fall of the Cholas, which of the following was the leading Tamil dynasty?","o":["Later Chalukyas","Hoysalas","Kakatiyas","Pandyas"],"a":3,"x":"After the Chola decline in the 13th century, the Pandyas of Madurai became the leading Tamil power, especially under Jatavarman Sundara Pandya.","e":"Marco Polo visited the Pandya kingdom in the 1290s.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0087","q":"Who among the following wrote 'Humayun-nama'?","o":["Gulbadan Begum","Abul Fazal","Nur Jahan","Abdul Rahim Khan-i-Khanan"],"a":0,"x":"Humayun-nama was written by Gulbadan Begum, Humayun's sister, at Akbar's request.","e":"Akbarnama and Ain-i-Akbari: Abul Fazl. Baburnama (Tuzuk-i-Baburi): Babur himself, in Turki.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0091","q":"Who among the following Delhi Sultans was called 'Lakh Baksh' because of his generosity?","o":["Qutbuddin Aibak","Ibrahim Lodhi","Muhammad bin Tughlaq","Iltutmish"],"a":0,"x":"Qutbuddin Aibak was called 'Lakh Baksh' (giver of lakhs) for his generosity.","e":"He began the Qutub Minar and built the Quwwat-ul-Islam mosque in Delhi; he died falling from a horse playing chaugan (polo).","src":["ASO 18 Aug 2025 S3"]},{"id":"q0121","q":"The empire of the Cholas was founded by which of the following rulers?","o":["Vikramaditya I","Vijayalaya","Vikramaditya II","Pulakesin II"],"a":1,"x":"Vijayalaya founded the imperial Chola line around 850 CE by capturing Thanjavur from the Muttaraiyars.","e":"Greatest Cholas: Rajaraja I (Brihadeeswara Temple) and Rajendra I (Gangaikondacholapuram).","src":["ASO 19 Aug 2025 S2"]},{"id":"q0166","q":"Cholas were the feudatory of which of the following political powers?","o":["The Rashtrakuta dynasty","The Pallava dynasty","The Chalukya dynasty","The Kadamba dynasty"],"a":1,"x":"The early Cholas of Uraiyur rose as feudatories of the Pallavas of Kanchi; Vijayalaya took Thanjavur around 850 CE.","e":"The Cholas later absorbed Pallava territory under Aditya I.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0206","q":"What was the name of the syncretic religion initiated by Akbar that combined elements from various faiths?","o":["Sulh-i-Kul","Din-i-Ilahi","Sufi-Islam","Mansabdari"],"a":1,"x":"Akbar started Din-i-Ilahi ('Religion of God') in 1582, drawing on several faiths; very few joined, Birbal among them.","e":"Sulh-i-kul, 'peace with all', was Akbar's wider policy of tolerance.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0248","q":"After being defeated by Sher Shah Suri, how did Humayun eventually regain the throne?","o":["Defeated Sher Shah in a direct battle","Waited for the decline of the Sur Empire and invaded Delhi","Formed an alliance with the Rajputs","Sought military support from Bahadur Shah of Gujarat"],"a":1,"x":"After losing to Sher Shah Suri (Chausa 1539, Kannauj 1540), Humayun lived in exile in Persia. He came back once the Sur empire weakened after Sher Shah's death, winning at Sirhind in 1555.","e":"He died in 1556 after falling down the stairs of his library, Sher Mandal, in Delhi.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0258","q":"Which of the following Delhi Sultans had set up an intelligence officer’s post called ‘Barid-i- Mumalik’?","o":["Alauddin Khalji","Muhammad Bin Tughlaq","Iltutmish","Balban"],"a":0,"x":"Alauddin Khalji built a strong spy network, headed by the barid-i-mumalik, with barids and munhiyans reporting to him.","e":"Balban had also used barids (news-writers).","src":["ASO 20 Aug 2025 S2"],"k":"Some books credit Balban with first organising barids; DSSSB's key names Alauddin Khalji."},{"id":"q0283","q":"Which of the following battles was NOT fought by Babur?","o":["Battle of Haldighati","Battle of Chanderi","Battle of Khanwa","Battle of Panipat"],"a":0,"x":"The Battle of Haldighati (1576) was fought between Akbar's army under Man Singh and Maharana Pratap, long after Babur's death in 1530.","e":"Babur's battles: Panipat (1526), Khanwa (1527), Chanderi (1528), Ghaghra (1529).","src":["ASO 20 Aug 2025 S3"]},{"id":"q0296","q":"Which of the following is considered a feature of Akbar's reign in terms of blending of architectural styles?","o":["Fatehpur Sikri Fort","Red Fort of Delhi","Jama Masjid of Agra","Taj Mahal of Agra"],"a":0,"x":"Fatehpur Sikri (1570s) blends Persian, Hindu and Jain styles, as in Buland Darwaza, Panch Mahal and Jodha Bai's palace, and shows Akbar's mixing of styles.","e":"The Taj Mahal and Red Fort of Delhi are Shah Jahan's.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0338","q":"Which of the following mosques was built by the Sultan of Delhi, Qutubuddin Aibak?","o":["Jami Masjid","Moth ki Masjid","Adina Mosque","Quwwat-ul-Islam Mosque"],"a":3,"x":"Qutbuddin Aibak built the Quwwat-ul-Islam Mosque (from 1193) in the Qutub complex, Delhi — the first mosque built in Delhi after the Turkish conquest.","e":"The Iron Pillar of Chandragupta II stands in its courtyard.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0339","q":"The significant work on music called Lahjat-i-Sikandar Shahi was prepared under which dynasty of the Delhi Sultanate?","o":["Mamluk Dynasty","Tughlaq Dynasty","Lodi Dynasty","Sayyid Dynasty"],"a":2,"x":"Lahjat-i-Sikandar Shahi, a Persian treatise on Indian music, was prepared under Sultan Sikandar Lodi of the Lodi dynasty.","e":"Sikandar Lodi founded Agra in 1504 and introduced the Gaz-i-Sikandari for land measurement.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0367","q":"Which of the following was the last dynasty to rule over the Vijayanagara empire?","o":["Saluva","Tuluva","Aravidu","Sangama"],"a":2,"x":"Vijayanagara had four dynasties: Sangama, Saluva, Tuluva and Aravidu. The Aravidu was the last, after defeat at Talikota (1565).","e":"Krishnadevaraya belonged to the Tuluva dynasty.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0369","q":"Which of the following sultans of Delhi made a significant contribution in giving shape to administrative institutions such as Iqtas, the army and the currency system?","o":["Qutubuddin Aibak","Shamsuddin Iltutmish","Ghiyasuddin Balban","Ibrahim Lodhi"],"a":1,"x":"Iltutmish shaped the Sultanate's institutions: the iqta system, a royal army, and the silver tanka and copper jital coins.","e":"He also formed the Turkan-i-Chahalgani (the Forty).","src":["ASO 21 Aug 2025 S3"]},{"id":"q0372","q":"Who among the following rulers built Jaipur city and made it a great centre of science and art?","o":["Raja Man Singh","Sawai Raja Jai Singh","Raja Ajit Singh","Raja Surajmal"],"a":1,"x":"Sawai Jai Singh II of Amber founded Jaipur in 1727 and built the Jantar Mantar observatories (Jaipur, Delhi, Ujjain, Varanasi, Mathura).","e":"Jaipur was planned by Vidyadhar Bhattacharya; the Jaipur Jantar Mantar is a UNESCO site.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0410","q":"Which Maratha commander was honoured by the Mughal emperor Shah Jahan with the jagir of Pune and a mansab of panch hazari?","o":["Maloji Bhosale","Jadhavrao","Shahaji Bhosale","Rajaram I"],"a":2,"x":"Shahaji Bhosale, father of Shivaji, briefly entered Shah Jahan's service around 1630 and received a mansab of 5,000 (panch hazari) with jagirs including Pune; he later served Ahmadnagar and then Bijapur.","e":"Shivaji was born at Shivneri fort in 1630 and grew up on the Pune jagir under his mother Jijabai.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0413","q":"The revenue system of the Mughals was called ___________.","o":["Sawar","Mansab","Zabt","Zat"],"a":2,"x":"The Mughal land revenue system was called zabt, based on measured land and average produce; under Akbar, Todar Mal developed it into the dahsala system.","e":"Zat and sawar were ranks in the mansabdari system, not revenue terms.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0446","q":"When was the first battle of Panipat fought?","o":["1526","1528","1525","1527"],"a":0,"x":"The First Battle of Panipat (21 April 1526): Babur defeated Ibrahim Lodi using field artillery and the tulughma tactic, founding the Mughal Empire.","e":"Second Panipat (1556): Akbar beat Hemu. Third Panipat (1761): Ahmad Shah Abdali beat the Marathas.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0460","q":"Which of the following dynasties initially established the Vijayanagar empire in the 14th century AD?","o":["Sangam","Arvidu","Tuluva","Saluva"],"a":0,"x":"Harihara I and Bukka Raya of the Sangama dynasty founded the Vijayanagar Empire in 1336, with the help of the sage Vidyaranya.","e":"The empire had four dynasties: Sangama → Saluva → Tuluva → Aravidu.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1566","q":"Which Mughal emperor was forced to leave his ancestral throne because of the invasion of another Mongol group?","o":["Babur","Jahangir","Akbar","Aurangzeb"],"a":0,"x":"Babur lost his ancestral kingdom of Fergana and Samarkand to the Uzbeks under Shaibani Khan, another Central Asian (Mongol-descended) group. He then took Kabul and later invaded India.","e":"Babur descended from Timur on his father's side and Genghis Khan on his mother's.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1574","q":"Vijayanagar Empire was ruled by four important dynasties. Which of the following is NOT one of these?","o":["Saluva","Yaduha","Aravidu","Tuluva"],"a":1,"x":"Vijayanagara's four dynasties: Sangama, Saluva, Tuluva and Aravidu. 'Yaduha' was not one.","e":"Sangama (1336) → Saluva (1485) → Tuluva (1505) → Aravidu (1570).","src":["Patwari 18 Sep 2022 S1"]},{"id":"q1584","q":"Which king of the Tuluva dynasty was the most famous king of the Vijayanagar Empire?","o":["Harihara I","Krishna Deva Raya","Bukka I","Ramaraya"],"a":1,"x":"Krishnadevaraya (1509–29) of the Tuluva dynasty was Vijayanagara's most celebrated king.","e":"The Portuguese traveller Domingo Paes described his capital, Hampi.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q1623","q":"The Slave dynasty was also called the ______.","o":["Khalji Dynasty","Lodhi Dynasty","Mamluk Dynasty","Tughlaq Dynasty"],"a":2,"x":"The Slave dynasty (1206–90) is also called the Mamluk dynasty, since Qutbuddin Aibak and several successors had been slaves ('mamluk').","e":"It is also called the Ilbari dynasty.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q0500","q":"Who among the following Mughal emperors was succeeded by Jahangir?","o":["Akbar","Humayun","Babur","Aurangzeb"],"a":0,"x":"Jahangir (Prince Salim) succeeded his father Akbar in 1605.","e":"Mughal order: Babur, Humayun, Akbar, Jahangir, Shah Jahan, Aurangzeb.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0502","q":"Who among the following was the founder of Utpala Dynasty?","o":["Krishnavarman","Gopalavarman","Avantivarman","Sankaravarman"],"a":2,"x":"Avantivarman founded the Utpala dynasty of Kashmir around 855 CE; his minister Suyya built irrigation works.","e":"Kalhana's Rajatarangini is the source for Kashmir's dynasties.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0539","q":"Who among the following was the founder of the Kalachuri Dynasty?","o":["Gangeyadeva","Kokalla II","Kokalla I","Ashoka"],"a":2,"x":"Kokalla I founded the Kalachuri dynasty of Tripuri (near Jabalpur, Madhya Pradesh) around 875 CE.","e":"Gangeyadeva and Lakshmikarna were its most powerful rulers.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0583","q":"When was the Second Battle of Tarain fought?","o":["1206","1210","1190","1192"],"a":3,"x":"In the Second Battle of Tarain (1192), Muhammad Ghori defeated Prithviraj Chauhan and opened north India to Turkish rule.","e":"In the First Battle of Tarain (1191), Prithviraj had won.","src":["Junior Assistant 21 Aug 2021 S3","Stenographer 23 Apr 2021 S2"]},{"id":"q0659","q":"Who among the following introduced Mansabdari System to organise the nobility and army?","o":["Akbar","Humayun","Babur","Aurangzeb"],"a":0,"x":"Akbar introduced the mansabdari system (1570s): every officer held a mansab (rank) with a zat (personal rank) and a sawar (number of horsemen).","e":"The Mughal ranks went from 10 to 10,000.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0662","q":"Who among the following was called Shahi-i- Bekhabar by Khafi Khan due to his appeasement parties by grants of title and rewards?","o":["Aurangzeb","Bahadur Shah I","Shah Jahan","Jahangir"],"a":1,"x":"The historian Khafi Khan called Bahadur Shah I 'Shah-i-Bekhabar' (the unaware king) for freely handing out titles and rewards to keep everyone happy.","e":"Bahadur Shah I (1707–12) succeeded Aurangzeb.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0663","q":"When was the Battle of Talikota fought?","o":["1565","1578","1603","1620"],"a":0,"x":"The Battle of Talikota (Rakshasi–Tangadi) was fought on 23 January 1565: the Deccan sultanates defeated Vijayanagara, and Hampi was sacked.","e":"Rama Raya of the Aravidu family was killed in the battle.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0740","q":"Which one of the following kings of the Vijayanagara empire belonged to the Tuluva dynasty?","o":["Harihara I","Krishnadevaraya","Thimma Bhupala","Sriranga I"],"a":1,"x":"Krishnadevaraya (1509–29) was the greatest ruler of Vijayanagara's Tuluva dynasty; he wrote the Telugu work 'Amuktamalyada'.","e":"His court had the Ashtadiggajas (eight poets).","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0741","q":"Which one of the following Sikh gurus standardized and popularized the Gurmukhi script?","o":["Guru Nanak","Guru Tegh Bahadur","Guru Angad","Guru Gobind Singh"],"a":2,"x":"Guru Angad Dev, the second Sikh Guru, standardised and popularised the Gurmukhi script.","e":"Guru Arjan Dev compiled the Adi Granth in 1604.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1311","q":"In which year did Timur captured Delhi?","o":["1405","1409","1398","1414"],"a":2,"x":"Timur (Tamerlane) invaded India and sacked Delhi in December 1398, during the reign of Nasiruddin Mahmud Tughlaq.","e":"Nadir Shah sacked Delhi in 1739 and took the Peacock Throne.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1348","q":"Captain Hawkins and Sir Thomas Roe visited the court of ___________.","o":["Aurangzeb","Shah Jahan","Humayun","Jahangir"],"a":3,"x":"Captain William Hawkins (1608) and Sir Thomas Roe (1615–19) visited Jahangir's court; Roe won trading rights for the English East India Company.","e":"Hawkins was given the title 'Khan' by Jahangir.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1040","q":"The Pala kings were the followers of which of the following faith?","o":["Buddhism","Jainism","Vaishnavism","Shaivism"],"a":0,"x":"The Pala kings of Bengal and Bihar (8th–12th century) were Buddhists: Dharmapala founded Vikramashila university and they supported Nalanda.","e":"Gopala, founder of the Pala dynasty, was elected by the nobles.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1049","q":"Which of the following rulers of the Rashtrakuta lineage is recognised for overpowering the Chola monarch Parantaka I and seizing the northern portion of the Chola dominion?","o":["Krishna III","Amoghavarsha I","Govinda III","Dantidurga"],"a":0,"x":"Rashtrakuta king Krishna III defeated Chola king Parantaka I's forces at the Battle of Takkolam (949 CE) and seized the northern Chola lands.","e":"Amoghavarsha I wrote the Kannada 'Kavirajamarga'.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1056","q":"Which Pandya king took the title 'Pallava Bhanjana' after defeating Nandivarman II several times together with the Chalukya ruler Vikramaditya II?","o":["Sundara Pandya","Jatila Parantaka (Srivallabha)","Maravarman Rajasimha I","Varaguna II"],"a":2,"x":"Pandya king Maravarman Rajasimha I (8th century), allied with Chalukya Vikramaditya II, defeated Pallava Nandivarman II several times and took the title 'Pallava Bhanjana' (breaker of the Pallavas).","e":"The Pandyas ruled from Madurai; Kanchi was the Pallava capital.","src":["PRT 20 Feb 2026 S2"]},{"id":"q1068","q":"In which year did Mehrunnisa marry Emperor Jahangir?","o":["1631","1619","1621","1611"],"a":3,"x":"Mehrunnisa married Jahangir in 1611 and was titled Nur Mahal, later Nur Jahan ('Light of the World').","e":"Her brother Asaf Khan's daughter Arjumand Banu became Mumtaz Mahal.","src":["PRT 20 Feb 2026 S2"]},{"id":"q1201","q":"What was the name of Iltutmish's daughter whom he appointed as his successor, but who faced resistance from nobles after his death?","o":["Shah Turkan","Nur Jahan","Razia","Jahanara"],"a":2,"x":"Iltutmish named his daughter Razia as successor; she became Sultan in 1236, the only woman to rule the Delhi Sultanate, but was overthrown by nobles in 1240.","e":"Shah Turkan was Iltutmish's wife and mother of Ruknuddin Firuz.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1239","q":"Which Vijayanagara ruler recaptured Raichur from the Bahmani successors?","o":["Harihara I","Krishnadevaraya","Bukka I","Deva Raya II"],"a":1,"x":"Krishnadevaraya won back the Raichur doab at the Battle of Raichur (1520), defeating Ismail Adil Shah of Bijapur, a successor state of the Bahmanis.","e":"The Raichur doab lies between the Krishna and Tungabhadra rivers.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1282","q":"Which historian described Razia's abilities as ruler of Delhi, after she came to the throne in 1236?","o":["Ibn Battuta","Amir Khusrau","Minhaj-us-Siraj","Firishta"],"a":2,"x":"Minhaj-us-Siraj, author of Tabaqat-i-Nasiri, described Razia (who took the throne in 1236) as able and wise, but said her being a woman counted against her with the nobles.","e":"Minhaj was the chief qazi of Delhi under Nasiruddin Mahmud.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1373","q":"The first Lodi ruler, Bahlul Lodi, ruled between ______.","o":["1454 CE and 1501 CE","1452 CE and 1499 CE","1453 CE and 1500 CE","1451 CE and 1489 CE"],"a":3,"x":"Bahlul Lodi, founder of the Lodi dynasty (the first Afghan dynasty at Delhi), ruled from 1451 to 1489.","e":"Sikandar Lodi (1489–1517) and Ibrahim Lodi (1517–26) followed.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1381","q":"At which gurudwara did Guru Gobind Singh establish the Khalsa Panth in 1699?","o":["Gurudwara Baba Atal Sahib","Gurudwara Takht Sri Patna Sahib","Gurudwara Anandpur Sahib","Gurudwara Harmandir Sahib"],"a":2,"x":"Guru Gobind Singh founded the Khalsa Panth on Baisakhi, 1699, at Anandpur Sahib (Punjab), today Takht Sri Keshgarh Sahib.","e":"The 'five Ks' were set down at that time.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1382","q":"Which of the following pairs is NOT correctly matched?","o":["Battle of Kannauj – 1540","Battle of Chanderi – 1544","Battle of Khanwa – 1527","Battle of Chausa – 1539"],"a":1,"x":"The Battle of Chanderi was fought in 1528 (Babur against Medini Rai), not 1544. The others are correct: Chausa 1539, Kannauj 1540, Khanwa 1527.","e":"Sher Shah defeated Humayun at Chausa and Kannauj.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1393","q":"The Battle of Khanwa (1527) was fought between the forces of Rana Sanga and ______.","o":["Babur","Mahmood Khalji","Isham Khan","Ibrahim Lodhi"],"a":0,"x":"At the Battle of Khanwa (1527) Babur defeated the Rajput confederacy led by Rana Sanga of Mewar and took the title 'Ghazi'.","e":"First Panipat (1526) was against Ibrahim Lodi.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1407","q":"Under whose rule were the southern kingdoms annexed to the Delhi Sultanate?","o":["Ulugh Khan","Shershah Suri","Mubarak Khalji","Nasiruddin Khan"],"a":2,"x":"Alauddin Khalji's raids made the southern kingdoms tributary, but annexation began under Mubarak Shah Khalji, who annexed Devagiri (Yadavas) in 1318; Warangal and Madurai followed under the Tughlaqs.","e":"Malik Kafur led Alauddin's southern campaigns.","src":["TGT 25 Jun 2023 S1"],"k":"Many books say the southern kingdoms were fully annexed under Muhammad bin Tughlaq (Ulugh Khan); DSSSB's key names Mubarak Khalji."},{"id":"q1418","q":"Who among the following planned to launch a military expedition to bring the Khurasan region under Delhi Sultanate’s submission?","o":["Muhammad Tughluq","Ghiyasuddin Khan","Ibrahim Lodi","Alauddin Khalji"],"a":0,"x":"Muhammad bin Tughlaq planned a military expedition to conquer Khurasan and raised a big army, but abandoned the plan.","e":"His other experiments: moving the capital to Daulatabad, and token (copper) currency.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1428","q":"Which Pala ruler founded the Vikramashila and Somapura universities, centres of Vajrayana Buddhism?","o":["Gopala","Devapala","Dharmapala","Mahipala"],"a":2,"x":"Pala king Dharmapala (about 770–810) founded Vikramashila university and the Somapura Mahavihara (Paharpur, Bangladesh), centres of Vajrayana Buddhism.","e":"Devapala supported Nalanda.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1451","q":"Which of the following used to be a unit of currency during the Delhi sultanate period?","o":["Paisa","Tola","Mann","Jittal"],"a":3,"x":"The jital was a copper coin of the Delhi Sultanate; Iltutmish introduced the silver tanka and copper jital.","e":"Sher Shah introduced the silver rupiya.","src":["TGT 25 Jun 2023 S3"]},{"id":"q1460","q":"Which of the following titles was assumed by the Chola King Rajendra I to commemorate his victory over the local kings after crossing the river Ganga?","o":["Vikramaditya","Gangaraj","Gangavijayi Chola","Gangaikonda Chola"],"a":3,"x":"Rajendra Chola I took the title 'Gangaikonda Chola' after his northern campaign reached the Ganga (around 1023) and built a new capital, Gangaikondacholapuram.","e":"He also led a naval expedition to Srivijaya (South-East Asia).","src":["TGT 25 Jun 2023 S3"]},{"id":"q1516","q":"Qutb-ud-din Aibak died in AD 1210, due to injuries sustained in a fall while playing which sport?","o":["Chaugan (Polo)","Sword fight","Wrestling","Archery"],"a":0,"x":"Qutbuddin Aibak died at Lahore in 1210 after falling from his horse while playing chaugan (polo).","e":"He is buried at Anarkali Bazaar, Lahore.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1534","q":"In the Mughal empire, whom did the term 'mansabdar' refer to?","o":["A person holding a position or rank","A trader","A horseman","A landlord owning 5,000 acres"],"a":0,"x":"A mansabdar was an officer holding a mansab (rank) in Akbar's system, which fixed his status, pay and the cavalry he kept.","e":"Zat = personal rank; sawar = cavalry number.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1561","q":"Which Chalukyan king shifted the capital from Manyakheta to Kalyani?","o":["Jayasimha II","Someswara I","Vikramaditya VI","Taila III"],"a":1,"x":"Someshvara I (1042–68) of the Western (Kalyani) Chalukyas moved the capital from Manyakheta to Kalyani (Basavakalyan, Karnataka).","e":"Vikramaditya VI started the Chalukya–Vikrama era; Bilhana wrote his biography.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0828","q":"Who among the following foreign travellers of the Mughal period stated that both Agra and Fatehpur Sikri were bigger cities than London?","o":["Ralph Fitch","Francisco Pelsaert","Anthony Monserrate","Francois Bernier"],"a":0,"x":"The English traveller Ralph Fitch, who visited Akbar's India around 1585, wrote that Agra and Fatehpur Sikri were each bigger than London.","e":"Francois Bernier (Shah Jahan–Aurangzeb) wrote 'Travels in the Mogul Empire'.","src":["PGT 26 Sep 2025"]}]},{"id":"modern","n":"Modern India (1757–1885)","qs":[{"id":"q0004","q":"In _____, Pandita Ramabai established _____ in Pune, a refuge for young widows who had been deserted and abused by their families.","o":["1869; the Women Care Mission","1889; the Mukti Mission","1879; a child care centre","1899; an old age home"],"a":1,"x":"Pandita Ramabai opened Sharada Sadan for widows in 1889, and her Mukti Mission counts its founding from that year; the large home at Kedgaon near Pune followed.","e":"Other women reformers: Savitribai Phule (first girls' school, Pune, 1848), Tarabai Shinde (Stri Purush Tulana, 1882).","src":["ASO 18 Aug 2025 S1"],"k":"Some books give 1898 for the Kedgaon (Mukti) home; DSSSB's key uses 1889."},{"id":"q0008","q":"In which of the following years was Oudh annexed to the British empire?","o":["1875","1856","1801","1843"],"a":1,"x":"Lord Dalhousie annexed Awadh (Oudh) in February 1856 on the ground of misgovernment, not under the Doctrine of Lapse. Nawab Wajid Ali Shah was sent to Calcutta.","e":"Awadh's annexation fed the 1857 revolt, since many Bengal Army sepoys came from Awadh.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0011","q":"Consider the following statements regarding the development of modern education in British India and select which statement(s) is/are correct. i. Sanskrit College was established by Jonathan Duncan in 1791 AD. ii. Calcutta Madrassa was established by Warren Hastings in 1781 AD. iii. ₹1 lakh was sanctioned for the development education in Charter Act, 1813.","o":["All i, ii and iii","Only i and iii","Only i","Only i and ii"],"a":0,"x":"All three statements are right: Calcutta Madrasa (Warren Hastings, 1781), Benares Sanskrit College (Jonathan Duncan, 1791), and the Charter Act of 1813, which set aside ₹1 lakh a year for education.","e":"Sequence: 1781 Madrasa → 1791 Sanskrit College → 1813 Charter Act → 1835 Macaulay's Minute → 1854 Wood's Despatch.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0050","q":"William Jones established the Asiatic Society of ______ in 1784 and remained its President till his death.","o":["Kerala","Puducherry","Bengal","Assam"],"a":2,"x":"Sir William Jones founded the Asiatic Society (of Bengal) in Calcutta in 1784 to study Asian languages, history and culture.","e":"Jones translated Kalidasa's Abhijnanashakuntalam into English (1789).","src":["ASO 18 Aug 2025 S2"]},{"id":"q0057","q":"The Paika Rebellion of 1817 took place in _________.","o":["Punjab","Madras","Orissa","Bengal"],"a":2,"x":"The Paika Rebellion of 1817 broke out in Khurda, Orissa, led by Bakshi Jagabandhu, against East India Company rule and its land revenue policy.","e":"Odisha asks for it to be called the 'First War of Independence', forty years before 1857.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0089","q":"Arrange the following famine commissions formed during the British period in the order of their establishment.","o":["MacDonnell < Lyall < Strachey < Campbell","MacDonnell < Lyall < Campbell < Strachey","Strachey < Campbell < MacDonnell < Lyall","Campbell < Strachey < Lyall < MacDonnell"],"a":3,"x":"Famine commissions in order: Campbell (1866, Orissa famine), Strachey (1880), Lyall (1898), MacDonnell (1901).","e":"The Strachey Commission led to the first Famine Code (1883).","src":["ASO 18 Aug 2025 S3"]},{"id":"q0090","q":"India's handicraft industries, particularly cotton and silk textiles, metalwork and precious stone crafts, enjoyed a global market before the arrival of the British because:","o":["high standards of craftsmanship was seen in all imports from India","there was no competition from other countries' products","products were extremely cheap","low quality of materials used"],"a":0,"x":"Indian cotton and silk textiles, metalwork and gem crafts sold worldwide before British rule because of their very high craftsmanship.","e":"Dhaka muslin and Masulipatnam chintz were prized in Europe.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0122","q":"Raja Ram Mohan Roy is also known as the Father of Indian ______________.","o":["Renaissance","Freedom Struggle","Nationalism","Constitution"],"a":0,"x":"Raja Ram Mohan Roy is called the Father of the Indian Renaissance; he founded the Brahmo Sabha (1828) and campaigned against sati, abolished in 1829.","e":"The Mughal emperor Akbar II gave him the title 'Raja'.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0167","q":"Which of the following events is considered as the beginning of the Revolt of 1857?","o":["The mutiny of sepoys at Meerut","Formation of the Indian National Congress","Partition of Bengal","Establishment of the East India Company"],"a":0,"x":"The 1857 revolt began with the mutiny of sepoys at Meerut on 10 May 1857; they marched to Delhi and proclaimed Bahadur Shah Zafar emperor.","e":"Mangal Pandey's attack at Barrackpore (29 March 1857) came earlier but stayed an isolated act.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0169","q":"Which Mysore ruler commanded the First Anglo-Mysore War fought against the British East India Company (EIC) in 1767?","o":["Shah Alam","Daud Khan Karrani","Hyder Ali","Alauddin Ali Shah"],"a":2,"x":"Hyder Ali of Mysore fought the First Anglo-Mysore War (1767–69), which ended with the Treaty of Madras.","e":"Tipu Sultan died in the Fourth War (1799) at Srirangapatna.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0220","q":"Which of the following universities was founded as Muhammedan-Anglo Oriental College by Sir Syed Ahmed Khan?","o":["Aligarh Muslim University","University of Lucknow","University of Allahabad","Bundelkhand University, Jhansi"],"a":0,"x":"Sir Syed Ahmed Khan founded the Muhammadan Anglo-Oriental College at Aligarh in 1875; it became Aligarh Muslim University in 1920.","e":"His movement for modern education among Muslims is called the Aligarh Movement.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0251","q":"Which of the following is known as the ‘First War of Independence ’ in the context of modern Indian history?","o":["Non-Cooperation Movement","Civil Disobedience Movement","Quit India Movement","Revolt of 1857"],"a":3,"x":"V. D. Savarkar called the Revolt of 1857 the 'First War of Indian Independence' in his 1909 book.","e":"The British called it the Sepoy Mutiny.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0286","q":"The Brahmo Samaj did NOT promote which of the following practices?","o":["Women education","Rejection of avatars and reincarnation","Monotheism","Idol worship"],"a":3,"x":"The Brahmo Samaj opposed idol worship. It preached monotheism, rejected avatars and rebirth, and pushed women's education.","e":"Arya Samaj (Dayananda Saraswati, 1875) also rejected idol worship.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0322","q":"Where was the International Headquarters of Theosophical Society established in India?","o":["Kodambakkam","Adambakkam","Adyar","Ayanavaram"],"a":2,"x":"The Theosophical Society (founded in New York in 1875 by Madame Blavatsky and Colonel Olcott) moved its international headquarters to Adyar, Madras, in 1882.","e":"Annie Besant later led it and started the Home Rule League (1916).","src":["ASO 21 Aug 2025 S2"]},{"id":"q0368","q":"Who commanded the British forces in month-long siege of Fort Seringapatam in 1799 during the Fourth Anglo-Mysore War?","o":["Robert Clive","George Harris","Claude Martin","Charles Dallas"],"a":1,"x":"Lieutenant-General George Harris commanded the British forces at the siege of Seringapatam (1799), where Tipu Sultan was killed; Arthur Wellesley served under him.","e":"The Governor-General then was Lord Wellesley.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0444","q":"_______ advocated the abolition of polygamy and child marriage, the rights of widows to remarry, condemned the subjugation of women and made sati a punishable offence.","o":["Debendranath Tagore","Raja Ram Mohan Roy","Ishwar Chandra Vidyasagar","Swami Dayanand Saraswati"],"a":1,"x":"Raja Ram Mohan Roy campaigned against polygamy, child marriage and sati, and for women's property rights; his efforts led to the 1829 ban on sati under Lord William Bentinck.","e":"He founded the Brahmo Sabha in 1828.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0452","q":"Due to the efforts of which of the following social reformers was the first Hindu Widow Remarriage Act introduced and passed in 1856?","o":["Bal Gangadhar Tilak","Atmaram Pandurang","Raja Ram Mohan Roy","Ishwar Chandra Vidyasagar"],"a":3,"x":"Ishwar Chandra Vidyasagar's campaign led to the Hindu Widows' Remarriage Act of 1856, passed under Lord Canning.","e":"The first legal widow remarriage under the Act was held in Calcutta in December 1856.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1577","q":"The third battle of Panipat was fought between the Maratha Empire and a coalition of the King of which of the following Empires in 1761?","o":["Durrani","Mughal","British","Persian"],"a":0,"x":"The Third Battle of Panipat (14 January 1761) was fought between the Marathas under Sadashivrao Bhau and Ahmad Shah Abdali (Durrani) with his allies; the Marathas were defeated.","e":"Ahmad Shah Durrani founded modern Afghanistan.","src":["Patwari 18 Sep 2022 S1"]},{"id":"q1581","q":"Who was born as Narendranath Dutta in Calcutta in January 1863?","o":["Raja Ram Mohan Roy","Bal Gangadhar Tilak","Ramakrishna Paramahansa","Swami Vivekananda"],"a":3,"x":"Swami Vivekananda was born Narendranath Datta in Calcutta on 12 January 1863, now observed as National Youth Day.","e":"He spoke at the Parliament of the World's Religions, Chicago, in 1893.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q1618","q":"The Battle of Poona in which Yashwantrao Holkar of Indore defeated combined armies of Peshwas and the Scindias, was fought in which year?","o":["1802","1867","1818","1832"],"a":0,"x":"In the Battle of Poona (October 1802) Yashwantrao Holkar defeated Peshwa Baji Rao II and Daulat Rao Scindia; the Peshwa fled and signed the Treaty of Bassein (1802) with the British.","e":"This led to the Second Anglo-Maratha War (1803–05).","src":["Patwari 20 Aug 2022 S1"]},{"id":"q0503","q":"Ishwar Chandra Vidyasagar started the first school for girl’s education in Calcutta in ________.","o":["1875","1849","1862","1898"],"a":1,"x":"Ishwar Chandra Vidyasagar backed J. E. D. Bethune in starting Calcutta's first girls' school (later Bethune School) in 1849, and went on to open many girls' schools.","e":"He also led the widow remarriage campaign (Act of 1856).","src":["Junior Assistant 21 Aug 2021 S1"],"k":"The 1849 school was formally founded by J. E. D. Bethune, with Vidyasagar as its secretary and a key supporter."},{"id":"q0540","q":"When was the Sadharan Brahmo Samaj of Calcutta founded?","o":["1866","1884","1878","1892"],"a":2,"x":"The Sadharan Brahmo Samaj was founded in 1878 after a split in Keshab Chandra Sen's Brahmo Samaj of India, led by Shivnath Shastri and Ananda Mohan Bose.","e":"Brahmo Samaj line: Brahmo Sabha (1828) → Adi Brahmo Samaj → Brahmo Samaj of India (1866) → Sadharan Brahmo Samaj (1878).","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0561","q":"Belur Math is a monastery near Kolkata in West Bengal founded by ___________.","o":["Ramakrishna Paramahamsa","Swami Vivekananda","Ram Mohan Roy","Ananda Mohan Bose"],"a":1,"x":"Swami Vivekananda founded Belur Math (1897–98), headquarters of the Ramakrishna Math and Mission, on the Hooghly near Kolkata.","e":"The Ramakrishna Mission was founded on 1 May 1897.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0580","q":"When was the Pitt's India Act passed?","o":["1792","1786","1780","1784"],"a":3,"x":"Pitt's India Act, 1784 set up the Board of Control, creating dual control of the Company's Indian territories by the Company and the Crown.","e":"It corrected flaws of the Regulating Act, 1773.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0581","q":"Who was the Governor General of India during the Fourth Anglo-Mysore War?","o":["Lord Bentinck","Lord Wellesley","Lord Canning","Lord Dalhousie"],"a":1,"x":"Lord Wellesley (1798–1805) was Governor-General during the Fourth Anglo-Mysore War (1799), in which Tipu Sultan died.","e":"Wellesley introduced the Subsidiary Alliance system.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0622","q":"The Ahmadiyya Movement was started in __________ by Mirza Ghulam Ahmed.","o":["1889","1870","1902","1852"],"a":0,"x":"Mirza Ghulam Ahmad founded the Ahmadiyya Movement at Qadian (Punjab) in 1889.","e":"It stood for modern education among Muslims along liberal lines.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0660","q":"Who among the following founded the Satyashodhak Samaj in 1873?","o":["Ramakrishna Bhandarkar","Mohadev Govind Ranade","Jyotirao Phule","Raja Rammohan Roy"],"a":2,"x":"Jyotirao Phule founded the Satyashodhak Samaj in Pune on 24 September 1873 to fight caste inequality and Brahminical dominance.","e":"His book 'Gulamgiri' (1873) attacked the caste system.","src":["Junior Assistant 25 Aug 2021 S3"]},{"id":"q0700","q":"The Bengal Sati Regulation which banned the Sati practice in all jurisdictions of British India was passed in _________.","o":["1792","1838","1850","1829"],"a":3,"x":"The Bengal Sati Regulation (Regulation XVII) of 4 December 1829, under Lord William Bentinck, banned sati across British India.","e":"Raja Ram Mohan Roy campaigned for it.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0742","q":"In which year did the Bastar rebellion take place?","o":["1910","1900","1905","1907"],"a":0,"x":"The Bhumkal (Bastar) rebellion of 1910 was a tribal uprising led by Gunda Dhur against British forest and land policies in Bastar.","e":"The Santhal Hul was in 1855; the Munda Ulgulan (Birsa Munda) in 1899–1900.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q0890","q":"Who among the following was NOT one of the three formidable players in southern Indian politics in the 1720s?","o":["The Nizam of Hyderabad","The Arcot Nawab","The Marathas","The Mysore rulers"],"a":3,"x":"In the 1720s the three big players in south India were the Nizam of Hyderabad, the Nawab of Arcot (Carnatic) and the Marathas. Mysore rose to that level later, under Hyder Ali.","e":"Nizam-ul-Mulk Asaf Jah founded Hyderabad state in 1724.","src":["PRT 16 Feb 2026 S3"]},{"id":"q1007","q":"Which tribal community dominated the Bastar region during British indirect rule?","o":["Juang","Santhal","Gond","Bhil"],"a":2,"x":"The Gond peoples (Maria and Muria Gonds among them) were the dominant tribal community of Bastar, alongside Dhurwas, Bhatras and Halbas, during British indirect rule through the Bastar king.","e":"Bastar's Bhumkal rebellion (1910) was led by Gunda Dhur.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1010","q":"During the Battle of Chinhat (1857), the British contingent suffered defeat under the command of which official?","o":["Henry Lawrence","John Nicholson","William Hodson","James Outram"],"a":0,"x":"At Chinhat near Lucknow (30 June 1857) rebels defeated a British force under Sir Henry Lawrence, who was killed days later during the siege of the Lucknow Residency.","e":"Begum Hazrat Mahal led the revolt at Lucknow.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1135","q":"Where did the French East India Company establish its first factory in 1668?","o":["Masulipattanam","Surat","Visakhapatnam","Patna"],"a":1,"x":"The French East India Company (formed 1664 under Colbert) set up its first Indian factory at Surat in 1668; Pondicherry (1674) became its headquarters.","e":"The Dutch first came to Masulipatnam (1605); the English to Surat (1613).","src":["PRT 26 Mar 2026 S2"]},{"id":"q1261","q":"When did the Ahom Revolt unfold in Assam as a resistance to British rule in the region?","o":["1830","1844","1828","1834"],"a":2,"x":"The Ahom revolt of 1828, led by Gomdhar Konwar, opposed British rule in Assam after the Treaty of Yandabo (1826).","e":"The Treaty of Yandabo ended the First Anglo-Burmese War.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1419","q":"The given pairs represent movements with the respective leaders. Which of these pairs is/are matched correctly? i.Koya Rebellion - Tomma Dora ii. Pabna Peasant Uprising - Bhagirath Manjhi iii. Kharwar Uprising - Shambhunath Pal","o":["Only ii","ii and iii","i and iii","Only i"],"a":3,"x":"Only (i) is correct: the Koya Rebellion (1879–80) was led by Tomma Dora. The Pabna uprising (1873) was led by Ishan Chandra Roy and Shambhu Pal; the Kharwar uprising by Bhagirath Manjhi.","e":"The Pabna peasants formed agrarian leagues against high rents.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1468","q":"In which year did the Battle of Seringapatam, a war between Mysore and the British, take place?","o":["1799","1764","1767","1805"],"a":0,"x":"The Battle (siege) of Seringapatam in 1799 ended the Fourth Anglo-Mysore War; Tipu Sultan was killed.","e":"The Wodeyar family was restored to Mysore under a subsidiary alliance.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1479","q":"Who among the following started the Young Bengal Movement in Calcutta?","o":["Dadabhai Naoroji","W.C. Bonnerji","Henry Derozio","A.O. Hume"],"a":2,"x":"Henry Louis Vivian Derozio, a teacher at Hindu College, Calcutta, inspired the radical Young Bengal Movement (1820s–30s).","e":"Derozio was dismissed from Hindu College in 1831.","src":["TGT 7 Feb 2024 S2"]},{"id":"q0850","q":"Match the movements with their founders: 1. Brahmo Samaj, 2. Arya Samaj, 3. Ramakrishna Mission, 4. Theosophical Society — a. Swami Vivekananda, b. Raja Ram Mohan Roy, c. Dayananda Saraswati, d. Annie Besant.","o":["1 - a, 2 - b, 3 - c, 4 - d","1 - b, 2 - c, 3 - a, 4 - d","1 - d, 2 - b, 3 - c, 4 - a","1 - b, 2 - a, 3 - d, 4 - c"],"a":1,"x":"Brahmo Samaj – Raja Ram Mohan Roy; Arya Samaj – Dayananda Saraswati; Ramakrishna Mission – Swami Vivekananda; Theosophical Society – linked with Annie Besant.","e":"Arya Samaj was founded in Bombay in 1875.","src":["PGT 14 Jul 2025"],"k":"The Theosophical Society was founded by Madame Blavatsky and Colonel Olcott (1875); Annie Besant led it later. DSSSB's key pairs it with Besant."}]},{"id":"freedom","n":"Freedom Struggle (1885–1947)","qs":[{"id":"q0048","q":"Pandit Madan Mohan Malaviya played an important role in the formation of which association?","o":["Indian National Congress","Arya Samaj","India League","Hindu Mahasabha"],"a":3,"x":"Madan Mohan Malaviya was a founder-leader of the Hindu Mahasabha (1915), four times Congress president, and founder of Banaras Hindu University (1916).","e":"He popularised the motto 'Satyameva Jayate'.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0086","q":"Assertion (A): The British government suppressed the publication of Al-Hilal. Reason (R): It began to advocate nationalist politics.","o":["A is true but R is false.","Statements A and R are true, and R is correct explanation of A.","R is true, but A is false.","Statements A and R are true, but R is not the correct explanation of A."],"a":1,"x":"Maulana Abul Kalam Azad started Al-Hilal (1912) to spread nationalist politics among Muslims; because it did, the British suppressed it in 1914. So A and R are both true and R explains A.","e":"Azad's next paper, Al-Balagh, was also banned, and he was interned in Ranchi.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0140","q":"Who among the following founded the revolutionary organisation Bharat Mata Society in 1907?","o":["Chandra Shekhar Azad","Bankim Chandra Chattopadhyay","Anand Mohan Bose","Ajit Singh"],"a":3,"x":"Ajit Singh (Bhagat Singh's uncle) founded the Bharat Mata Society in Punjab in 1907, with Sufi Amba Prasad, to oppose the colonisation laws.","e":"Ajit Singh and Lala Lajpat Rai were deported to Mandalay in 1907.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0162","q":"The statue at Kolkata Maidan, dedicated to a revolutionary woman fondly known as 'Gandhi buri', is that of:","o":["Kanaklata Barua","Aruna Asaf Ali","Bhikaiji Cama","Matangini Hazra"],"a":3,"x":"Matangini Hazra, called 'Gandhi Buri' (old lady Gandhi), was shot dead at 73 while leading a Quit India procession at Tamluk, Bengal, in 1942.","e":"Kanaklata Barua of Assam was also shot while carrying the flag in 1942, at 17.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0178","q":"Who was the first leader of the Muslim League which was established in the year 1906?","o":["Syed Amir Ali","Syed Ahmed Khan","Nawab Abdul Latif","Aga Khan"],"a":3,"x":"The All-India Muslim League was founded at Dhaka in December 1906, and Sir Aga Khan III was its first honorary president.","e":"The Dhaka session was hosted by Nawab Salimullah.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0204","q":"Netaji Subhash Chandra Bose was the mayor of which of the following Municipal Corporations in 1930-1931?","o":["North 24 Parganas","Durgapur","Siliguri","Calcutta"],"a":3,"x":"Subhas Chandra Bose was elected Mayor of the Calcutta Corporation in 1930, having earlier served as its Chief Executive Officer under C. R. Das.","e":"Bose was Congress president at Haripura (1938) and Tripuri (1939).","src":["ASO 20 Aug 2025 S1"]},{"id":"q0219","q":"The Cabinet Mission Plan aimed to _____.","o":["abolish the zamindari system","partition India","propose a framework for India’s independence","provide full independence to India"],"a":2,"x":"The Cabinet Mission (1946: Pethick-Lawrence, Stafford Cripps, A. V. Alexander) proposed a framework for independence: a united India, a Constituent Assembly and an interim government.","e":"It rejected a separate Pakistan; the Constituent Assembly it proposed first met on 9 December 1946.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0241","q":"Who among the following was born in 1889 in Allahabad?","o":["Jawaharlal Nehru","Subhas Chandra Bose","Sardar Vallabhbhai Patel","Mahatma Gandhi"],"a":0,"x":"Jawaharlal Nehru was born in Allahabad (Prayagraj) on 14 November 1889; his birthday is observed as Children's Day.","e":"Anand Bhawan in Prayagraj was the Nehru family home.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0260","q":"Bhagat Singh killed which of the following British officers?","o":["John Saunders","Michael O'Dwyer","James Scott","Reginald Dyer"],"a":0,"x":"In December 1928 Bhagat Singh and Rajguru shot J. P. Saunders in Lahore, avenging Lala Lajpat Rai's death. They had meant to target James Scott.","e":"Udham Singh killed Michael O'Dwyer in London in 1940.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0284","q":"Who among the following was born in Porbandar in 1869?","o":["Sardar Patel","Subhas Chandra Bose","JL Nehru","Mahatma Gandhi"],"a":3,"x":"Mohandas Karamchand Gandhi was born at Porbandar, Gujarat, on 2 October 1869, now observed as Gandhi Jayanti and the International Day of Non-Violence.","e":"He returned to India from South Africa on 9 January 1915, marked as Pravasi Bharatiya Divas.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0294","q":"In which of the following years was the Quit India Movement launched?","o":["1935","1945","1940","1942"],"a":3,"x":"The Quit India Movement was launched on 8 August 1942 at the Gowalia Tank maidan, Bombay, with Gandhi's call 'Do or Die'.","e":"August Kranti Maidan is the new name of Gowalia Tank.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0327","q":"During World War I, who among the following lived in the US, where he founded the Indian Home Rule League of America (1917)?","o":["Bhikaji Cama","Ajit Singh","Bal Gangadhar Tilak","Lala Lajpat Rai"],"a":3,"x":"Lala Lajpat Rai lived in the USA during World War I and founded the Indian Home Rule League of America in New York in 1917.","e":"In India, the Home Rule Leagues were started in 1916 by Tilak (Belgaum) and Annie Besant (Madras).","src":["ASO 21 Aug 2025 S2"]},{"id":"q0330","q":"In 1913, who among the following formed the Ghadar Party in San Francisco to organise a rebellion against the British Government of India?","o":["Lala Lajpat Rai","Lala Hardayal","Bhagat Singh","Ajit Singh"],"a":1,"x":"Lala Har Dayal founded the Ghadar Party at San Francisco in 1913 (Sohan Singh Bhakna was its first president) to organise an armed revolt against British rule.","e":"It was named after its weekly paper 'Ghadar'.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0376","q":"In which of the following years was the Hunter Commission formed to enquire about the Jallianwala Bagh massacre?","o":["1934","1903","1917","1919"],"a":3,"x":"The Hunter Committee (Disorders Inquiry Committee) was set up in October 1919 to inquire into the Jallianwala Bagh massacre of 13 April 1919.","e":"The Congress ran its own inquiry, with Gandhi among its members.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0401","q":"The Khilafat Movement continued for the period ____________.","o":["1919-1925","1919-1920","1919-1922","1919-1930"],"a":2,"x":"The Khilafat Movement ran from 1919 to about 1922, when it ended after the Chauri Chaura incident stopped Non-Cooperation, and Turkey abolished the Caliphate in 1924.","e":"Leaders: the Ali brothers (Muhammad Ali and Shaukat Ali), Maulana Azad, Hakim Ajmal Khan.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0412","q":"After the Gandhi–Irwin Pact, Gandhi agreed to take part in which Round Table Conference?","o":["Third","Fourth","First","Second"],"a":3,"x":"Under the Gandhi–Irwin Pact (March 1931), Gandhi called off Civil Disobedience and attended the Second Round Table Conference in London (September–December 1931) as the Congress's sole representative.","e":"The Congress boycotted the First (1930) and Third (1932) conferences.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0447","q":"The famous battle cry ‘Chalo Dilli’ by Subash Chandra Bose was given during the formation of which of the following groups?","o":["Forward Bloc","Azad Hind Fauj","Gadar Party","Theosophical Society"],"a":1,"x":"Subhas Chandra Bose gave the call 'Chalo Dilli' in 1943 when he took charge of the Azad Hind Fauj (Indian National Army) in Singapore.","e":"He also said 'Give me blood, and I will give you freedom'.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1567","q":"Which of the following statements is correct?","o":["Viceroy Curzon partitioned Bengal in 1905.","Viceroy Curzon partitioned Bengal in 1903.","Viceroy Curzon partitioned Bengal in 1901.","Viceroy Curzon partitioned Bengal in 1904."],"a":0,"x":"Lord Curzon partitioned Bengal on 16 October 1905, observed as a day of mourning; the Swadeshi movement followed.","e":"Tagore started Raksha Bandhan as a symbol of unity against the partition.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1613","q":"In which year was the Civil Disobedience Movement called off?","o":["1932","1930","1931","1934"],"a":2,"x":"The first phase of the Civil Disobedience Movement was called off after the Gandhi–Irwin Pact in March 1931.","e":"It resumed in 1932 and was formally withdrawn in 1934.","src":["Patwari 17 Sep 2022 S3"],"k":"Some books take 1934, when the movement was finally withdrawn; DSSSB's key marks 1931."},{"id":"q0499","q":"In 1916, the Lucknow Pact was signed between ____________.","o":["Indian National Congress and British","Indian National Congress and Muslim League","British and Sikh","Sikh and Indian National Congress"],"a":1,"x":"The Lucknow Pact (1916) was signed by the Indian National Congress and the Muslim League; the Congress accepted separate electorates for Muslims.","e":"Tilak and Jinnah were its architects; the moderate and extremist Congress factions reunited the same year.","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0501","q":"When did the Cripps Mission come to India?","o":["1935","1912","1928","1942"],"a":3,"x":"The Cripps Mission came to India in March 1942, promising dominion status after the war; Gandhi called it a 'post-dated cheque'.","e":"Its failure led to the Quit India Movement (August 1942).","src":["Junior Assistant 21 Aug 2021 S1"]},{"id":"q0541","q":"When did the Khilafat movement start?","o":["1928","1892","1919","1935"],"a":2,"x":"The Khilafat Movement began in 1919, against the harsh treatment of Turkey (seat of the Khalifa) after World War I; 17 October 1919 was observed as Khilafat Day.","e":"Gandhi joined Khilafat with Non-Cooperation in 1920.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0542","q":"Which among the following movements was also known as the August Movement?","o":["Khilafat Movement","Quit India Movement","Simon Go Back Movement","Dandi March"],"a":1,"x":"The Quit India Movement was called the August Movement (August Kranti) because it began on 8–9 August 1942.","e":"9 August is observed as August Kranti Divas.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0543","q":"When was the Akali movement started?","o":["1930","1925","1920","1935"],"a":2,"x":"The Akali Movement (Gurdwara Reform Movement) began in 1920 to free Sikh gurdwaras from corrupt mahants; it led to the Sikh Gurdwaras Act of 1925.","e":"The SGPC and the Akali Dal were formed in 1920.","src":["Junior Assistant 21 Aug 2021 S2"]},{"id":"q0579","q":"The __________ was also called the White Flowing River because all the people that were joining the procession were wearing white khadi.","o":["Khilafat Movement","Quit India Movement","Salt March","Non Cooperation Movement"],"a":2,"x":"The Salt March (Dandi March, 1930) was likened to a 'white flowing river' because marchers in white khadi stretched out along the road.","e":"Gandhi walked about 385 km from Sabarmati to Dandi, 12 March – 6 April 1930.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0582","q":"Who presided over the Congress Session of Banaras in 1905?","o":["Gopal Krishan Gokhale","Dadabhai Naoroji","Pherozeshah Mehta","Subash Chandra Bose"],"a":0,"x":"Gopal Krishna Gokhale presided over the 1905 Benaras session of the Indian National Congress, which backed Swadeshi against the Partition of Bengal.","e":"1906 Calcutta session: Dadabhai Naoroji, who first stated Swaraj as the goal.","src":["Junior Assistant 21 Aug 2021 S3"]},{"id":"q0619","q":"When was the Indian Independence Act passed?","o":["January 1947","December 1947","July 1947","March 1947"],"a":2,"x":"The Indian Independence Act was passed by the British Parliament in July 1947 (royal assent on 18 July), creating India and Pakistan from 15 August 1947.","e":"It was based on the Mountbatten Plan of 3 June 1947.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0620","q":"Which among the following plan is also known as \"Breakdown Plan\"?","o":["Wavell Plan","Dalhousie Plan","Cornwallis Plan","Bentinck Plan"],"a":0,"x":"Lord Wavell's 1945 proposal is remembered as the 'Breakdown Plan': a phased British withdrawal if talks failed. It was discussed at the Simla Conference.","e":"The Simla Conference broke down over the Muslim League's claim to nominate all Muslim members.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0621","q":"Who among the following was not an Extremist leader?","o":["Bipin Chandra Pal","Bal Gangadhar Tilak","Lala Lajpat Rai","Dadabhai Naoroji"],"a":3,"x":"Dadabhai Naoroji was a Moderate who gave the 'drain of wealth' theory. The Extremists were Lal-Bal-Pal: Lala Lajpat Rai, Bal Gangadhar Tilak and Bipin Chandra Pal.","e":"The Congress split into Moderates and Extremists at Surat in 1907.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0623","q":"Who among the following was the first Governor General of Independent India?","o":["Lord Cornwallis","Lord Dalhousie","Lord Bentinck","Lord Mountbatten"],"a":3,"x":"Lord Mountbatten was the first Governor-General of independent India (August 1947 – June 1948); C. Rajagopalachari was the first and only Indian Governor-General.","e":"Mountbatten was also the last Viceroy of British India.","src":["Junior Assistant 25 Aug 2021 S2"]},{"id":"q0661","q":"In ___________, Jinnah proposed ‘Fourteen Points’ for safeguarding the rights and interests of the Muslims in any future constitution of the country.","o":["1943","1939","1907","1928"],"a":3,"x":"Jinnah put forward his Fourteen Points as the Muslim League's answer to the Nehru Report of 1928; they were presented at the League session in March 1929.","e":"The Nehru Report (Motilal Nehru, 1928) rejected separate electorates.","src":["Junior Assistant 25 Aug 2021 S3"],"k":"The Fourteen Points are usually dated March 1929; 1929 is not an option, and DSSSB's key takes 1928, the year of the Nehru Report they answered."},{"id":"q0701","q":"The Simla Conference of _________ was a meeting between the Viceroy of India Lord Wavell and the major political leaders of British India at Simla.","o":["1945","1919","1928","1936"],"a":0,"x":"The Simla Conference (June–July 1945) between Viceroy Wavell and Indian leaders discussed the Wavell Plan for a new Executive Council.","e":"It failed over the Muslim League's claim to nominate all Muslim members.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0702","q":"The Indian Council Act passed in 1909 was popularly known as ________________.","o":["Wavell Plan","Charter Act","Morley Minto Reforms","Pitt's India Act"],"a":2,"x":"The Indian Councils Act, 1909 is known as the Morley–Minto Reforms (Secretary of State John Morley, Viceroy Lord Minto); it introduced separate electorates for Muslims.","e":"Montagu–Chelmsford Reforms = Government of India Act, 1919.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0703","q":"The Surat Split was the splitting of the Indian National Congress into two groups - the Extremists and the Moderates - at the Surat session in _________.","o":["1918","1907","1932","1885"],"a":1,"x":"The Congress split into Moderates and Extremists at the Surat session in December 1907, presided over by Rash Behari Ghosh.","e":"They reunited at Lucknow in 1916.","src":["Junior Assistant 31 Aug 2021 S1"]},{"id":"q0743","q":"Which one of the following was the venue for Mahatma Gandhi's Quit India speech in 1942?","o":["Sabarmati Ashram","Cellular Jail","Red Fort","Gowalia Tank Maidan"],"a":3,"x":"Gandhi gave the 'Quit India' / 'Do or Die' speech at Gowalia Tank Maidan, Bombay, on 8 August 1942.","e":"Aruna Asaf Ali hoisted the Congress flag there on 9 August 1942.","src":["Junior Assistant 31 Aug 2021 S2"]},{"id":"q1290","q":"In which year's session of the Indian National Congress was Vande Mataram sang for the first time?","o":["1896","1899","1898","1897"],"a":0,"x":"'Vande Mataram' was first sung at a Congress session in 1896 (Calcutta session), by Rabindranath Tagore.","e":"'Jana Gana Mana' was first sung at the Calcutta session of 1911.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1332","q":"The first session of Indian National Congress to be presided by a lady was held in _______.","o":["1888","1917","1929","1920"],"a":1,"x":"Annie Besant presided over the 1917 Calcutta session, the first woman president of the Congress.","e":"The first Indian woman president was Sarojini Naidu (Kanpur, 1925).","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1345","q":"Who among the following wrote the Bengali song 'Vande Mataram'?","o":["Rabindranath Tagore","Subhas Chandra Bose","Bankim Chandra Chatterjee","Bal Gangadhar Tilak"],"a":2,"x":"'Vande Mataram' was written by Bankim Chandra Chattopadhyay and first published in his novel 'Anandamath' (1882).","e":"It was adopted as the national song on 24 January 1950.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1359","q":"Who among the following was known as \"The Political Guru of Mahatma Gandhi\"?","o":["Dadabhai Naoroji","Bal Gangadhar Tilak","Gopal Krishna Gokhale","Jawaharlal Nehru"],"a":2,"x":"Gandhi called Gopal Krishna Gokhale his political guru.","e":"Gokhale founded the Servants of India Society in 1905.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q0965","q":"While deported to Mandalay in 1908 for allegedly seditious articles in 'Kesari', which important work did Bal Gangadhar Tilak write?","o":["Gita-Saar","Gita-Darshan","Gita-Rahasya","Gita-Gyan"],"a":2,"x":"While jailed at Mandalay (Burma) for sedition over his Kesari articles (1908–14), Tilak wrote 'Gita Rahasya', a commentary on the Bhagavad Gita stressing Karma Yoga.","e":"Tilak also wrote 'The Arctic Home in the Vedas'.","src":["PRT 18 Feb 2026 S3"]},{"id":"q0995","q":"Who among the following led the anti-partition (of Bengal) movement under the Moderates?","o":["Bhagat Singh","Surendranath Banerjee","Jawaharlal Nehru","Mahatma Gandhi"],"a":1,"x":"Surendranath Banerjee led the Moderates' campaign against the Partition of Bengal (1905) through petitions, meetings and the press (his paper 'The Bengalee').","e":"He was called 'Rashtraguru' and founded the Indian Association (1876).","src":["PRT 19 Feb 2026 S1"]},{"id":"q1013","q":"After the First Round Table Conference, when the Congress appointed a negotiator for direct talks with Lord Irwin, who was chosen?","o":["Mahatma Gandhi","Subhas Chandra Bose","Sardar Patel","Jawaharlal Nehru"],"a":0,"x":"After the First Round Table Conference, the Congress chose Gandhi to talk directly with Lord Irwin, which led to the Gandhi–Irwin Pact (5 March 1931).","e":"The Karachi session (1931) endorsed the pact.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1052","q":"Who among the following gave the famous slogan “Swaraj is my birthright and I shall have it” during the Indian National Movement?","o":["Bipin Chandra Pal","Bal Gangadhar Tilak","Lala Lajpat Rai","Gopal Krishna Gokhale"],"a":1,"x":"Bal Gangadhar Tilak declared 'Swaraj is my birthright and I shall have it' (1916, Home Rule movement).","e":"Tilak was called 'Lokmanya'; the British called him the 'Father of Indian Unrest'.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1071","q":"In which city was the All India Muslim League founded in 1906?","o":["Dhaka","Calcutta (Kolkata)","Lucknow","Bombay (Mumbai)"],"a":0,"x":"The All-India Muslim League was founded at Dhaka on 30 December 1906, at a meeting hosted by Nawab Salimullah.","e":"Aga Khan III was its first honorary president.","src":["PRT 20 Feb 2026 S2"]},{"id":"q1142","q":"Who said, 'The real progress of India did not mean simply the growth and expansion of industrial urban centers but mainly the development of the villages.'?","o":["Rabindranath Tagore","Mahatma Gandhi","Subhash Chandra Bose","Jawaharlal Nehru"],"a":1,"x":"Mahatma Gandhi held that India's real progress lay in developing its villages, not only its industrial cities ('India lives in her villages').","e":"His idea of Gram Swaraj stressed self-sufficient villages.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1208","q":"Where was the first session of the Indian National Congress held?","o":["Lucknow","Bombay","Lahore","Delhi"],"a":1,"x":"The first session of the Indian National Congress was held in Bombay (Gokuldas Tejpal Sanskrit College) in December 1885, presided over by W. C. Bonnerjee, with 72 delegates.","e":"A. O. Hume was a founder of the INC.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1242","q":"Who was the first Indian woman to become a Governor in the Dominion of India?","o":["Vijaya Lakshmi Pandit","Sarojini Naidu","Indira Gandhi","Sucheta Kripalani"],"a":1,"x":"Sarojini Naidu, the 'Nightingale of India', became Governor of the United Provinces in 1947 — the first woman Governor in the Dominion of India.","e":"She was also the first Indian woman Congress president (Kanpur, 1925).","src":["PRT 3 Apr 2026 S2"]},{"id":"q1268","q":"Who among the following leaders founded the Indian Home Rule Society?","o":["Lala Lajpat Rai","Mahatma Gandhi","Shyamji Krishna Varma","Motilal Nehru"],"a":2,"x":"Shyamji Krishna Varma founded the Indian Home Rule Society in London in 1905, along with India House and the paper 'The Indian Sociologist'.","e":"India House trained revolutionaries such as V. D. Savarkar and Madan Lal Dhingra.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1376","q":"Alfred High School, where Mahatma Gandhi completed his school education, is in which city of Gujarat?","o":["Rajkot","Ahmedabad","Bhavnagar","Porbandar"],"a":0,"x":"Mahatma Gandhi finished his schooling at Alfred High School, Rajkot (now Mahatma Gandhi Museum), where his father was a diwan.","e":"Gandhi studied law at University College London.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1440","q":"Who was the first Asian to be elected to the British Parliament, in 1892?","o":["Subhas Chandra Bose","Dadabhai Naoroji","Jawahar Lal Nehru","Dinyar Patel"],"a":1,"x":"Dadabhai Naoroji became the first Asian elected to the British House of Commons, in 1892, from Finsbury Central as a Liberal.","e":"He was called the 'Grand Old Man of India'.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1462","q":"Who signed the Poona Pact on behalf of Hindus and MK Gandhi?","o":["M M Malaviya","V J Patel","S C Bose","J L Nehru"],"a":0,"x":"The Poona Pact (24 September 1932) was signed by Madan Mohan Malaviya for the Hindus and Gandhi, and by Dr B. R. Ambedkar for the Depressed Classes.","e":"It replaced separate electorates with reserved seats in joint electorates.","src":["TGT 25 Jun 2023 S3"]},{"id":"q1494","q":"When were the Morley–Minto Reforms passed by the British Parliament?","o":["1909","1908","1911","1910"],"a":0,"x":"The Morley–Minto Reforms (Indian Councils Act) were passed by the British Parliament in 1909.","e":"They introduced separate electorates for Muslims.","src":["TGT 29 Aug 2025"]},{"id":"q1508","q":"In which of the following years was the Indian National Congress established?","o":["1895","1856","1876","1885"],"a":3,"x":"The Indian National Congress was founded in December 1885 in Bombay, with A. O. Hume as a founder and W. C. Bonnerjee as its first president.","e":"Dadabhai Naoroji and Dinshaw Wacha were among the founders.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1529","q":"Who presided over the Indian National Congress session held at Bombay in 1885?","o":["A. O. Hume","Jawaharlal Nehru","Mahatma Gandhi","W. C. Bonnerjee"],"a":3,"x":"W. C. Bonnerjee presided over the first session of the Indian National Congress in Bombay in December 1885.","e":"A. O. Hume was the founder-general secretary.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1553","q":"In 1940 Udham Singh killed a British officer in London. Who was the officer and why was he targeted?","o":["Lord Zetland – Secretary of State for India, targeted for supporting colonial repression","Jack Gibson – a British officer unconnected with the Jallianwala Bagh massacre","Michael O'Dwyer – to avenge his role in the Jallianwala Bagh massacre","Charles Innes – a former Viceroy of India, targeted for unrelated colonial policies"],"a":2,"x":"In March 1940 Udham Singh shot Sir Michael O'Dwyer in London, avenging the Jallianwala Bagh massacre (1919), when O'Dwyer was Lieutenant-Governor of Punjab.","e":"Udham Singh was hanged in July 1940 at Pentonville Prison.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0773","q":"Which newspaper was started by Bal Gangadhar Tilak in the English language?","o":["Kesari","India Wins Freedom","Swaraj","Mahratta"],"a":3,"x":"Bal Gangadhar Tilak ran two newspapers: 'Kesari' in Marathi and 'Mahratta' in English (both from 1881).","e":"'India Wins Freedom' is Maulana Azad's book, not a newspaper.","src":["PGT 25 Sep 2025"]},{"id":"q0774","q":"Which legislative Act was responsible for the creation of the Federal Court of India?","o":["Government of India Act, 1936","Government of India Act, 1919","Indian Councils Act, 1909","Indian Independence Act, 1947"],"a":0,"x":"The Federal Court of India was created by the Government of India Act, 1935 and began work in Delhi in 1937; the Supreme Court replaced it in 1950.","e":"The same Act brought provincial autonomy and proposed an All-India Federation.","src":["PGT 25 Sep 2025"],"k":"The option printed in the paper says '1936', but the Act is of 1935. It is still the intended answer."},{"id":"q0779","q":"What was the main reason for the widespread movement in India against the arrival of the Simon Commission in 1928?","o":["It increased land revenue on peasants.","It had no Indian member.","It abolished local self-government.","It recommended the partition of India."],"a":1,"x":"The Simon Commission (1927–28), sent to review the 1919 reforms, had seven British members and no Indian — so Indians greeted it with 'Simon Go Back'.","e":"Lala Lajpat Rai was injured in a lathi-charge during a protest at Lahore and died soon after.","src":["PGT 25 Sep 2025"]},{"id":"q0794","q":"In which year was the Rowlatt Act passed, which led to widespread protests across India?","o":["1919","1920","1942","1935"],"a":0,"x":"The Rowlatt Act (March 1919) allowed detention without trial; Gandhi launched the Rowlatt Satyagraha against it, and the Jallianwala Bagh massacre followed.","e":"It was called the 'Black Act'.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0803","q":"Which significant event marked the beginning of the Extremist Phase in the Indian National Movement in 1905?","o":["The Partition of Bengal","The Jallianwala Bagh Massacre","The formation of the Indian National Congress","The Quit India Movement"],"a":0,"x":"The Partition of Bengal (1905) began the Extremist phase (1905–1918), with Swadeshi and boycott led by Lal-Bal-Pal and Aurobindo.","e":"The partition was annulled in 1911.","src":["PGT 22 Sep 2025"]},{"id":"q0812","q":"Who among the following reinterpreted the Vedanta philosophy to base his concept of nationalism?","o":["Lala Lajpat Rai","Aurobindo Ghose","Bal Gangadhar Tilak","Bipin Chandra Pal"],"a":1,"x":"Aurobindo Ghose reinterpreted Vedanta to give nationalism a spiritual basis, seeing the nation as the Mother and freedom as a divine mission.","e":"He edited 'Bande Mataram' and later settled in Pondicherry.","src":["PGT 22 Sep 2025"]},{"id":"q0832","q":"Who moved the main resolution on non-cooperation in the annual session of the Congress in Nagpur in 1920?","o":["C R Das","Subhash C Bose","Rajendra Prasad","Jawaharlal Nehru"],"a":0,"x":"At the Nagpur session (December 1920), C. R. Das moved the main resolution on non-cooperation.","e":"The session also set up linguistic Provincial Congress Committees.","src":["PGT 26 Sep 2025"]},{"id":"q0861","q":"Under whose leadership was the no-tax campaign of the Bardoli Satyagraha organised?","o":["Vithalbhai Patel","Rajendra Prasad","Vallabhbhai Patel","Mahatma Gandhi"],"a":2,"x":"The Bardoli Satyagraha (1928) in Gujarat, a no-tax campaign against a 22% rise in land revenue, was led by Vallabhbhai Patel. The women of Bardoli gave him the title 'Sardar'.","e":"The Kheda Satyagraha (1918) was led by Gandhi with Patel.","src":["PGT 24 Sep 2025"]}]}]});
